CREATE TABLE t_bit (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  c_bit12 BIT(12) DEFAULT NULL,
  c_bit1 BIT(1) DEFAULT NULL,
  c_bit64 BIT(64) DEFAULT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

